API = class {
    constructor(postman, verbose = false, baseUrl = 'http://localhost:8080') {
        this.baseUrl = baseUrl;
        this.pm = postman;
        this._verbose = verbose;
    }
    async addUser(user) {
        return this.post('/admin/users', user);
    }
    async addCategory(category) {
        return this.post('/admin/categories', category);
    }
    async addEvent(userId, event) {
        return this.post('/users/' + userId + '/events', event);
    }
    async addComment(userId, eventId, comment) {
        return this.post('/users/' + userId + '/events/' + eventId + '/comments', comment);
    }
    async publishEvent(eventId) {
        return this.patch('/admin/events/' + eventId, { stateAction: 'PUBLISH_EVENT' });
    }
    async publishComment(commentId) {
        return this.patch('/admin/comments/' + commentId + '?stateAction=PUBLISH', null);
    }
    async post(path, body) {
        return this.sendRequest('POST', path, body);
    }
    async patch(path, body) {
        return this.sendRequest('PATCH', path, body);
    }
    async sendRequest(method, path, body = null) {
        return new Promise((resolve, reject) => {
            const request = {
                url: this.baseUrl + path,
                method: method,
                body: body ? JSON.stringify(body) : '',
                header: { 'Content-Type': 'application/json' }
            };
            this.pm.sendRequest(request, (error, response) => {
                if (error || (response.code >= 400 && response.code <= 599)) {
                    reject(error || response);
                    return;
                }
                if (response.stream.length === 0) {
                    resolve(null);
                    return;
                }
                try { resolve(response.json()); } catch(e) { resolve(response.text()); }
            });
        });
    }
};
RandomUtils = class {
    constructor() {}
    getUser() {
        return { name: pm.variables.replaceIn('{{$randomFullName}}'), email: pm.variables.replaceIn('{{$randomEmail}}') };
    }
    getCategory() {
        return { name: pm.variables.replaceIn('{{$randomWord}}') + Math.floor(Math.random() * 10000) };
    }
    getEvent(categoryId) {
        return {
            annotation: pm.variables.replaceIn('{{$randomLoremParagraph}}'),
            category: categoryId,
            description: pm.variables.replaceIn('{{$randomLoremParagraphs}}'),
            eventDate: this.getFutureDateTime(),
            location: { lat: parseFloat(pm.variables.replaceIn('{{$randomLatitude}}')), lon: parseFloat(pm.variables.replaceIn('{{$randomLongitude}}')) },
            paid: pm.variables.replaceIn('{{$randomBoolean}}'),
            participantLimit: parseInt(pm.variables.replaceIn('{{$randomInt}}')),
            requestModeration: pm.variables.replaceIn('{{$randomBoolean}}'),
            title: pm.variables.replaceIn('{{$randomLoremSentence}}')
        };
    }
    getFutureDateTime() {
        let moment = require('moment');
        let m = moment();
        m.add(5, 'hour');
        return m.format('YYYY-MM-DD HH:mm:ss');
    }
};
